import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty list when no invoices are overdue', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.value.number);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], issued.value.dueDate);
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-11-05');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.value.number);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const result = overdueInvoices([paid.value], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, paid.value.number);
});

test('overdueInvoices excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(draft.ok, true);

  const result = overdueInvoices([draft.value], '2026-11-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const result = overdueInvoices([paid.value], '2026-11-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns invoice details', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-11-10');
  assert.equal(result.length, 1);

  const invoice = result[0];
  assert.equal(invoice.number, issued.value.number);
  assert.equal(invoice.customerId, 'C-002');
  assert.equal(invoice.dueDate, issued.value.dueDate);
  assert.equal(typeof invoice.daysOverdue, 'number');
  assert(invoice.daysOverdue > 0);
  assert.equal(typeof invoice.due, 'number');
  assert.equal(invoice.due, invoiceTotals(issued.value).total);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-11-10');
  assert.equal(result.length, 1);

  const expectedDaysOverdue = 4;
  assert.equal(result[0].daysOverdue, expectedDaysOverdue);
});

test('overdueInvoices calculates due with partial payment', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const totals = invoiceTotals(issued.value);

  const result = overdueInvoices([paid.value], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - 20000);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 7 }],
  });
  assert.equal(inv3.ok, true);
  const issued3 = issueInvoice(inv3.value, []);
  assert.equal(issued3.ok, true);

  const result = overdueInvoices([issued1.value, issued2.value, issued3.value], '2026-11-20');
  assert.equal(result.length, 3);
  assert(result[0].daysOverdue > result[1].daysOverdue);
  assert(result[1].daysOverdue > result[2].daysOverdue);
});

test('overdueInvoices handles empty invoice list', () => {
  const result = overdueInvoices([], '2026-11-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices with multiple customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const result = overdueInvoices([issued1.value, issued2.value], '2026-11-10');
  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-002');
});

test('overdueInvoices with invoices from multiple years', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const result = overdueInvoices([issued1.value, issued2.value], '2026-11-10');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, issued2.value.number);
  assert.equal(result[1].number, issued1.value.number);
});

test('overdueInvoices with invoices having different due dates', () => {
  const invoices = [];

  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-09-${String(i).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });
    assert.equal(inv.ok, true);
    const issued = issueInvoice(inv.value, []);
    assert.equal(issued.ok, true);
    invoices.push(issued.value);
  }

